import json
from glob import glob
def task_func(directory, string):
    json_files = []
    for path in glob(f"{directory}/**/*.json", recursive=True):
        json_files.append(path)

    result = []
    for file_path in json_files:
        with open(file_path, 'r') as f:
            try:
                data = json.load(f)
            except json.JSONDecodeError:
                continue
            if _search_json(data, string):
                result.append(file_path)
    return result
def _search_json(data, string):
    if isinstance(data, dict):
        for key, value in data.items():
            if key == string or _search_json(value, string):
                return True
    elif isinstance(data, list):
        for item in data:
            if _search_json(item, string):
                return True
    else:
        return str(data) == string
    return False

