import json
import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return {"data": {}, "value_counts": Counter()}
    def clean_item(item):
        if isinstance(item, dict):
            return {k: clean_item(v) for k, v in item.items() if v is not None}
        elif isinstance(item, list):
            return [clean_item(i) for i in item if i is not None]
        elif isinstance(item, str):
            email_pattern = r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'
            return re.sub(email_pattern, REPLACE_NONE, item)
        else:
            return item
    processed = clean_item(data)
    flat_vals = []
    def flatten_values(obj):
        if isinstance(obj, dict):
            for v in obj.values():
                flatten_values(v)
        elif isinstance(obj, list):
            for i in obj:
                flatten_values(i)
        else:
            flat_vals.append(obj)
    flatten_values(processed)
    counts = Counter(flat_vals)
    return {"data": processed, "value_counts": counts}

