import pandas as pd
import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError:
        raise ValueError("Malformed JSON data")
    if not data or not isinstance(data, list):
        raise ValueError("Empty or invalid JSON structure")
    report_data = []
    for entry in data:
        if not isinstance(entry, dict):
            raise ValueError("Each entry must be a dictionary")
        country = entry.get("Country")
        population = entry.get("Population")
        if not isinstance(country, str):
            raise ValueError("Country name must be a string")
        if not isinstance(population, (int, float)):
            raise ValueError("Population must be numeric")
        if population < 0:
            raise ValueError("Population cannot be negative")
        report_data.append([country, math.floor(population)])
    df = pd.DataFrame(report_data, columns=["Country", "Population"])
    file_path = os.path.join(output_dir, file_name)
    try:
        df.to_csv(file_path, index=False)
    except IOError:
        raise IOError("Cannot write to specified directory")
    return file_path, df
